BEGIN;
UPDATE public.config SET value='true' WHERE key='multi_tenant_enabled';
INSERT INTO auth.users(id,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data) VALUES('ce8f8da2-0e18-4200-bb52-977aac215332','pages-rollback@example.invalid',now(),'{}','{}');
SELECT set_config('request.jwt.claims','{"sub":"ce8f8da2-0e18-4200-bb52-977aac215332","role":"authenticated"}',true);
SET LOCAL ROLE authenticated;
SELECT public.tenant_onboard('Páginas rollback');
RESET ROLE;
SELECT set_config('request.jwt.claims',jsonb_build_object('sub','ce8f8da2-0e18-4200-bb52-977aac215332','role','authenticated','app_metadata',(SELECT raw_app_meta_data FROM auth.users WHERE id='ce8f8da2-0e18-4200-bb52-977aac215332'))::text,true);
DO $$ DECLARE tid uuid:=public.get_tenant_id();p jsonb;r jsonb;sid uuid:=gen_random_uuid();visitor uuid:=gen_random_uuid();eid uuid:=gen_random_uuid();lid uuid;f jsonb;pid uuid;stage uuid;mid uuid;blocked boolean:=false;c jsonb;cid uuid:=gen_random_uuid();tok uuid;sid2 uuid:=gen_random_uuid();BEGIN
 p:=public.web_pages_admin('create',NULL,'{"name":"QA Landing","url":"https://landing.example/imersao"}');
 IF jsonb_array_length(public.web_pages_admin('list'))<>1 THEN RAISE EXCEPTION 'list';END IF;
 PERFORM public.web_collect((p->>'key')::uuid,'https://landing.example','/imersao',sid,visitor,eid,'pageview',NULL,'instagram');
 PERFORM public.web_collect((p->>'key')::uuid,'https://landing.example','/imersao',sid,visitor,eid,'pageview',NULL,'instagram');
 PERFORM public.web_collect((p->>'key')::uuid,'https://landing.example','/imersao',sid,visitor,gen_random_uuid(),'click','Participar');
 r:=public.web_pages_admin('report',(p->>'id')::uuid);
 IF r->>'views'<>'1' OR r->>'clicks'<>'1' OR r->>'visitors'<>'1' OR r->>'leads'<>'0' THEN RAISE EXCEPTION 'metrics %',r;END IF;
 BEGIN PERFORM public.web_collect((p->>'key')::uuid,'https://wrong.example','/imersao',sid,visitor,gen_random_uuid(),'pageview');EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'origin guard';END IF;
 SELECT id INTO pid FROM public.sales_pipelines WHERE tenant_id=tid LIMIT 1;
 SELECT id INTO stage FROM public.sales_pipeline_stages WHERE pipeline_id=pid AND NOT is_won AND NOT is_lost LIMIT 1;
 SELECT id INTO mid FROM public.team_members WHERE tenant_id=tid LIMIT 1;
 f:=public.forms_admin('save_publish',NULL,jsonb_build_object('name','QA Landing Form','fields','[{"id":"nome","type":"text","label":"Nome","required":true,"map_to":"nome"},{"id":"email","type":"email","label":"Email","required":true,"map_to":"email"}]'::jsonb,'style','{}'::jsonb,'settings',jsonb_build_object('pipeline_id',pid,'stage_id',stage,'responsible_id',mid)));
 PERFORM public.forms_public_submit((f->>'id')::uuid,gen_random_uuid(),'{"nome":"Lead da landing","email":"landing@example.invalid"}',jsonb_build_object('crm_page',p->>'id','crm_session',sid),repeat('a',64));
 r:=public.web_pages_admin('report',(p->>'id')::uuid);
 IF r->>'conversions'<>'1' OR r->>'leads'<>'1' THEN RAISE EXCEPTION 'conversion %',r;END IF;
 SELECT id INTO lid FROM public.leads WHERE tenant_id=tid AND email='landing@example.invalid';
 IF (SELECT count(*) FROM public.lead_interactions WHERE lead_id=lid AND interaction_type='page_activity')<>2 THEN RAISE EXCEPTION 'timeline';END IF;
 -- Further activity is identified, duplicate attribution cannot steal the session.
 PERFORM public.web_collect((p->>'key')::uuid,'https://landing.example','/imersao',sid,visitor,gen_random_uuid(),'pageview');
 IF (SELECT count(*) FROM public.lead_interactions WHERE lead_id=lid AND interaction_type='page_activity')<>3 THEN RAISE EXCEPTION 'return visit';END IF;
 PERFORM crm_web.bind(gen_random_uuid(),lid,NULL,jsonb_build_object('page_id',p->>'id','session_id',sid));
 blocked:=false;BEGIN PERFORM public.web_pages_admin('get',gen_random_uuid());EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'tenant guard';END IF;
 IF has_function_privilege('authenticated','public.web_collect(uuid,text,text,uuid,uuid,uuid,text,text,text,text,text,text)','EXECUTE') OR has_schema_privilege('authenticated','crm_web','USAGE') THEN RAISE EXCEPTION 'public read leak';END IF;
 c:=public.inbound_admin('create',cid,'{"name":"QA Canal tracking"}');tok:=(c->>'token')::uuid;
 c:=public.inbound_admin('save',cid,jsonb_build_object('name','QA Canal tracking','pipeline_id',pid,'stage_id',stage,'method','fixed','members',jsonb_build_array(mid),'mappings','[{"source":"nome","target":"name","required":true},{"source":"email","target":"email","required":true}]'::jsonb),1);
 c:=public.inbound_admin('status',cid,'{"status":"active"}',(c->>'revision')::int);
 PERFORM public.web_collect((p->>'key')::uuid,'https://landing.example','/imersao',sid2,visitor,gen_random_uuid(),'pageview');
 r:=public.inbound_receive(tok,gen_random_uuid(),jsonb_build_object('nome','Outro lead','email','external-landing@example.invalid','_crm_tracking',jsonb_build_object('page_id',p->>'id','session_id',sid2)));
 IF r->>'status'<>'processed' THEN RAISE EXCEPTION 'external form %',r;END IF;
 r:=public.web_pages_admin('report',(p->>'id')::uuid);
 IF r->>'conversions'<>'2' OR r->>'visitors'<>'1' THEN RAISE EXCEPTION 'external attribution %',r;END IF;
 PERFORM public.web_pages_admin('status',(p->>'id')::uuid,'{"active":false}');blocked:=false;
 BEGIN PERFORM public.web_collect((p->>'key')::uuid,'https://landing.example','/imersao',sid,visitor,gen_random_uuid(),'pageview');EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'pause failed';END IF;
END $$;
ROLLBACK;
